-- Generated by generate.py (SQLite/ANSI compatible). Injected anomaly rows intentionally violate some FKs;
-- keep PRAGMA foreign_keys=OFF when loading the full seed, or generate with --no-anomalies.

CREATE TABLE learner (
  learner_id TEXT NOT NULL,
  signup_date DATE NOT NULL,
  country TEXT NOT NULL,
  education_level TEXT NOT NULL,
  preferred_format TEXT NOT NULL,
  cohort TEXT NOT NULL,
  status TEXT NOT NULL,
  PRIMARY KEY (learner_id)
);

CREATE TABLE course (
  course_id TEXT NOT NULL,
  title TEXT NOT NULL,
  subject_area TEXT NOT NULL,
  status TEXT NOT NULL,
  created_at DATE NOT NULL,
  PRIMARY KEY (course_id)
);

CREATE TABLE skill (
  skill_id TEXT NOT NULL,
  course_id TEXT NOT NULL,
  name TEXT NOT NULL,
  level INTEGER NOT NULL,
  status TEXT NOT NULL,
  created_at DATE NOT NULL,
  PRIMARY KEY (skill_id),
  FOREIGN KEY (course_id) REFERENCES course(course_id)
);

CREATE TABLE skill_prerequisite (
  skill_id TEXT NOT NULL,
  prerequisite_skill_id TEXT NOT NULL,
  min_mastery REAL NOT NULL,
  effective_from DATE NOT NULL,
  effective_to DATE,
  PRIMARY KEY (skill_id, prerequisite_skill_id),
  FOREIGN KEY (skill_id) REFERENCES skill(skill_id),
  FOREIGN KEY (prerequisite_skill_id) REFERENCES skill(skill_id)
);

CREATE TABLE content_item (
  content_id TEXT NOT NULL,
  course_id TEXT NOT NULL,
  title TEXT NOT NULL,
  format TEXT NOT NULL,
  difficulty INTEGER NOT NULL,
  duration_min INTEGER NOT NULL,
  pass_mark INTEGER NOT NULL,
  status TEXT NOT NULL,
  published_at DATE,
  retired_at DATE,
  PRIMARY KEY (content_id),
  FOREIGN KEY (course_id) REFERENCES course(course_id)
);

CREATE TABLE content_skill (
  content_id TEXT NOT NULL,
  skill_id TEXT NOT NULL,
  weight REAL NOT NULL,
  is_primary INTEGER NOT NULL,
  PRIMARY KEY (content_id, skill_id),
  FOREIGN KEY (content_id) REFERENCES content_item(content_id),
  FOREIGN KEY (skill_id) REFERENCES skill(skill_id)
);

CREATE TABLE learning_path (
  path_id TEXT NOT NULL,
  learner_id TEXT NOT NULL,
  course_id TEXT NOT NULL,
  target_skill_id TEXT NOT NULL,
  status TEXT NOT NULL,
  created_at TIMESTAMP NOT NULL,
  closed_at TIMESTAMP,
  PRIMARY KEY (path_id),
  FOREIGN KEY (learner_id) REFERENCES learner(learner_id),
  FOREIGN KEY (course_id) REFERENCES course(course_id),
  FOREIGN KEY (target_skill_id) REFERENCES skill(skill_id)
);

CREATE TABLE learning_path_event (
  event_id TEXT NOT NULL,
  path_id TEXT NOT NULL,
  event_seq INTEGER NOT NULL,
  event_type TEXT NOT NULL,
  from_status TEXT,
  to_status TEXT NOT NULL,
  event_ts TIMESTAMP NOT NULL,
  skill_id TEXT,
  content_id TEXT,
  mastery_after REAL,
  attempt_id TEXT,
  PRIMARY KEY (event_id),
  FOREIGN KEY (path_id) REFERENCES learning_path(path_id),
  FOREIGN KEY (skill_id) REFERENCES skill(skill_id),
  FOREIGN KEY (content_id) REFERENCES content_item(content_id),
  FOREIGN KEY (attempt_id) REFERENCES attempt(attempt_id)
);

CREATE TABLE attempt (
  attempt_id TEXT NOT NULL,
  learner_id TEXT NOT NULL,
  content_id TEXT NOT NULL,
  path_id TEXT NOT NULL,
  attempt_no INTEGER NOT NULL,
  started_at TIMESTAMP NOT NULL,
  submitted_at TIMESTAMP NOT NULL,
  duration_sec INTEGER NOT NULL,
  score REAL NOT NULL,
  max_score REAL NOT NULL,
  passed INTEGER NOT NULL,
  recommendation_id TEXT,
  PRIMARY KEY (attempt_id),
  FOREIGN KEY (learner_id) REFERENCES learner(learner_id),
  FOREIGN KEY (content_id) REFERENCES content_item(content_id),
  FOREIGN KEY (path_id) REFERENCES learning_path(path_id),
  FOREIGN KEY (recommendation_id) REFERENCES recommendation(recommendation_id)
);

CREATE TABLE assessment_result (
  result_id TEXT NOT NULL,
  attempt_id TEXT NOT NULL,
  learner_id TEXT NOT NULL,
  skill_id TEXT NOT NULL,
  score_pct REAL NOT NULL,
  mastery_before REAL,
  mastery_after REAL NOT NULL,
  proficiency_band TEXT NOT NULL,
  recorded_at TIMESTAMP NOT NULL,
  PRIMARY KEY (result_id),
  FOREIGN KEY (attempt_id) REFERENCES attempt(attempt_id),
  FOREIGN KEY (learner_id) REFERENCES learner(learner_id),
  FOREIGN KEY (skill_id) REFERENCES skill(skill_id)
);

CREATE TABLE recommendation (
  recommendation_id TEXT NOT NULL,
  learner_id TEXT NOT NULL,
  path_id TEXT NOT NULL,
  content_id TEXT NOT NULL,
  target_skill_id TEXT NOT NULL,
  issued_at TIMESTAMP NOT NULL,
  reason_code TEXT NOT NULL,
  rationale TEXT NOT NULL,
  target_skill_mastery REAL,
  prereq_margin REAL,
  difficulty_gap INTEGER NOT NULL,
  rank_score REAL NOT NULL,
  as_of_attempt_id TEXT,
  model_version TEXT NOT NULL,
  status TEXT NOT NULL,
  resolved_at TIMESTAMP,
  outcome_attempt_id TEXT,
  outcome_score REAL,
  outcome_passed INTEGER,
  PRIMARY KEY (recommendation_id),
  FOREIGN KEY (learner_id) REFERENCES learner(learner_id),
  FOREIGN KEY (path_id) REFERENCES learning_path(path_id),
  FOREIGN KEY (content_id) REFERENCES content_item(content_id),
  FOREIGN KEY (target_skill_id) REFERENCES skill(skill_id),
  FOREIGN KEY (as_of_attempt_id) REFERENCES attempt(attempt_id),
  FOREIGN KEY (outcome_attempt_id) REFERENCES attempt(attempt_id)
);

CREATE TABLE recommendation_event (
  event_id TEXT NOT NULL,
  recommendation_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  event_ts TIMESTAMP NOT NULL,
  attempt_id TEXT,
  PRIMARY KEY (event_id),
  FOREIGN KEY (recommendation_id) REFERENCES recommendation(recommendation_id),
  FOREIGN KEY (attempt_id) REFERENCES attempt(attempt_id)
);
